        .collect();
    let mut all = Vec::new();
    for h in handles {
        all.extend(h.await.unwrap());
    }
    all.sort();
    println!("{all:?}");
    let left: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM jobs WHERE NOT done").fetch_one(&pool).await.unwrap();
    println!("осталось {left}");
}

